  QString manualGrouped=QetFormatting::groupedBomQuery(true,true,true,false);manualGrouped.insert(manualGrouped.lastIndexOf(" ORDER BY")," WHERE manufacturer='Maker'");ElementQueryWidget opaque;opaque.setQuery(manualGrouped);auto *opaqueSql=opaque.findChild<QCheckBox*>("m_edit_sql_query_cb");check(opaqueSql->isChecked()&&opaque.queryStr()==manualGrouped,"query19 edited marked SQL remains Advanced without false canonical recognition");opaqueSql->setChecked(false);QMetaObject::invokeMethod(&opaque,"on_m_edit_sql_query_cb_clicked",Qt::DirectConnection);check(QetTableQuery15::withoutState(opaque.queryStr())==manualGrouped&&run(opaque.queryStr())==2,"query19 explicit result-projection conversion preserves manual grouped WHERE");
  ElementQueryWidget renamedGroup;renamedGroup.usePredefined18("grouped");auto *groupChosen=renamedGroup.findChild<QListWidget*>("m_choosen_list");for(int i=0;i<groupChosen->count();++i){auto *item=groupChosen->item(i);if(item->text()=="No."||item->text()=="References"){const QString name=item->text()=="No."?"Nr":"Device refs";item->setData(Qt::UserRole,item->data(Qt::UserRole).toString()+" AS "+QetTableQuery15::quotedName(name));item->setText(name);}}QTimer::singleShot(0,[](){if(auto *dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))if(auto *buttons=dialog->findChild<QDialogButtonBox*>())buttons->button(QDialogButtonBox::Ok)->click();});renamedGroup.findChild<QPushButton*>("groupedBom13Button")->click();check(renamedGroup.selectedFieldExpressions().size()==7&&renamedGroup.queryStr().contains("AS \"Nr\"")&&renamedGroup.queryStr().contains("AS \"Device refs\""),"query19 grouped options preserve renamedNoRefs without duplicatecolumns");
